"""Literal product units, authored mappings and paid crop/handling recipe; not diet adequacy."""
from decimal import Decimal as Q,ROUND_CEILING
q=lambda x:Q(str(x))
ceil=lambda x:int(q(x).to_integral_value(rounding=ROUND_CEILING))
def compute(cfg,pb,pbr,old,path,crop_scale=1):
 f=cfg['food'];products=f['products'];mapping=f['mapping'];rows={v['id']:v for v in pb['basket'] if v['purpose']=='01'}
 if set(rows)!=set(mapping):raise ValueError('Uninterpreted food purpose/component')
 private={k:Q(0) for k in products};public={k:Q(0) for k in products};unit={}
 for source,targets in mapping.items():
  if sum(q(v) for v in targets.values())!=1:raise ValueError('Unbalanced product mapping')
  r=rows[source];weights={age:q(w) for age,w in zip(pb['child_age_order'],r['child_quantity_weights'])};people=q(pbr['population']['working']+pbr['population']['older'])+sum(q(pbr['population'][age])*w for age,w in weights.items());quantity=q(r['annual_quantity'])*people
  for target,share in targets.items():
   if target not in products or products[target]['unit']!=r['unit']:raise ValueError('Uninterpreted unit/product conversion')
   private[target]+=quantity*q(share);public[target]+=q(f['institutional_meals'])*q(f['meal_ingredients_each'][source])*q(share)
 packing=q(old['food']['packing_yield']);distribution=q(old['food']['distribution_yield']);seed=q(f['seed_fraction']);out=[];fieldhours=Q(0);holding=Q(0);cropgross=Q(0);packed=Q(0);border_mass=Q(0);irrigation=Q(0);reservequote=Q(0);annualFX=Q(0);seedquote=Q(0);ownlandquote=Q(0)
 for name,p in products.items():
  receive=private[name]+public[name];share=q(p['mixed_share'] if path=='mixed' else p['bulk_share'])
  if path=='mixed' and name in cfg['bounded_crop_rival']['scaled_new_crop_products']:share*=q(crop_scale)
  domestic=receive*share;border=receive*(1-share)/distribution;massfactor=Q(1) if p['unit']=='kg' else q(f['liquid_kg_litre_transport_only']);field=area=hours=water=Q(0);crop=old['food']['crop_recipes'].get(name)
  if domestic:
   if p['unit']!='kg' or crop is None:raise ValueError('Unsupported domestic product recipe')
   field=domestic/(packing*distribution*(1-seed))/1000;area=field/q(crop['yield_t_ha']);cover=area/(1-q(old['food']['rotation_land_fraction']))-area;hours=area*q(crop['work_hours_ha'])+cover*q(old['food']['cover_hours_ha']);water=area*q(crop['net_irrigation_m3_ha'])/q(old['food']['field_irrigation_efficiency']);holding+=area+cover;ownlandquote+=(area+cover)*q(f['farm_equipment_stock_CU_ha']);seedquote+=field*1000*seed*q(p['import_FU_unit'])*q(f['seed_initial_price_multiplier'])
  stock=receive*q(f['reserve_days'])/365/distribution if p['reserve'] else Q(0);fx=border*q(p['import_FU_unit'])+stock*q(f['reserve_spoil'])*q(p['import_FU_unit']);annualFX+=fx;reservequote+=stock*q(p['import_FU_unit']);fieldhours+=hours;cropgross+=field*(1-seed);packed+=domestic/distribution/1000;border_mass+=border*massfactor/1000;irrigation+=water
  out.append({'id':name,'unit':p['unit'],'private_received_units':private[name],'public_received_units':public[name],'received_units':receive,'domestic_received_units':domestic,'border_import_units':border,'gross_harvest_t':field,'retained_seed_t':field*seed,'packing_input_t':field*(1-seed),'packing_side_t':field*(1-seed)*(1-packing),'domestic_distribution_loss_units':domestic/distribution-domestic,'import_distribution_loss_units':border-receive*(1-share),'holding_ha':area/(1-q(old['food']['rotation_land_fraction'])) if domestic else Q(0),'field_cover_hours':hours,'farm_customer_m3':water,'initial_reserve_border_units':stock,'annual_spoil_border_units':stock*q(f['reserve_spoil']),'annual_import_FU':fx,'harvest30_extra_import_units':domestic*q('.3')/distribution,'harvest30_extra_import_FU':domestic*q('.3')/distribution*q(p['import_FU_unit']),'import30day_received_units_at_risk':receive*(1-share)*30/365,'safe_diet_or_product_equivalence':None})
 bulk=packed+border_mass;tonnekm=packed*q(old['food']['domestic_tonne_km'])+border_mass*q(old['food']['import_tonne_km'])+bulk*q(old['food']['final_tonne_km']);km=tonnekm/q(old['food']['truck_carried_tonnes'])*(1+q(old['food']['empty_return_km_fraction']));freighthours=km/q(old['food']['truck_speed_km_h'])+2*bulk/q(old['food']['truck_carried_tonnes'])*q(old['food']['driver_handling_hours_trip']);H=q(cfg['annual_task_hours'])
 rolehours={'field':fieldhours,'packing':cropgross*q(old['food']['processing_hours_gross_tonne']),'handling':bulk*q(old['food']['bulk_handling_hours_tonne']),'freight':freighthours,'retail':q(old['food']['retail_outlets'])*q(old['food']['retail_daily_hours'])*365*q(old['food']['retail_simultaneous_people'])};roles={k:ceil(v/H) for k,v in rolehours.items()};peakavailable=(q(f['harvest_weeks'])*q(f['peak_paid_hours_week'])-q(f['peak_break_hours'])-q(f['peak_paid_leave_hours'])-q(f['peak_holiday_hours'])-q(f['peak_learning_hours']))*q(f['peak_attendance_fraction']);peak=ceil(fieldhours*q(f['harvest_fraction_of_field_hours'])/peakavailable);extra=max(0,peak-roles['field']);seasonpay=q(extra)*q(cfg['pay']['frontline'])*q(f['harvest_weeks'])/52
 trucks=ceil(km/q(f['truck_annual_km']));stock=ownlandquote+q(f['packing_storage_stock_CU'])+q(old['food']['retail_outlets'])*q(f['retail_stock_each_CU'])+trucks*q(f['truck_stock_each_CU']);renew=(stock-trucks*q(f['truck_stock_each_CU']))/q(cfg['asset_life_years']['food'])+trucks*q(f['truck_stock_each_CU'])/q(cfg['asset_life_years']['truck']);diesel=km*q(old['food']['diesel_litres_vehicle_km']);power=cropgross*q(old['food']['processing_MWh_gross_tonne'])/1000+bulk*q(old['food']['cold_chain_MWh_bulk_tonne'])/1000+irrigation*q(old['food']['irrigation_kWh_m3'])/1000000
 return {'path':path,'chosen_new_water_crop_share_scale':q(crop_scale),'products':out,'private_kg':sum(v['private_received_units'] for v in out if v['unit']=='kg'),'private_litres':sum(v['private_received_units'] for v in out if v['unit']=='litre'),'public_kg':sum(v['public_received_units'] for v in out if v['unit']=='kg'),'public_litres':sum(v['public_received_units'] for v in out if v['unit']=='litre'),'holding_ha':holding,'processing_input_t':cropgross,'food_handled_transport_t':bulk,'farm_customer_m3':irrigation,'roles':roles,'role_hours':rolehours,'core_people':sum(roles.values()),'seasonal_additional_people':extra,'seasonal_peak_usable_hours_each':peakavailable,'seasonal_pay_CU':seasonpay,'core_pay_CU':q(sum(roles.values()))*q(cfg['pay']['frontline']),'operating_input_import_FU':(q(sum(roles.values()))*q(cfg['pay']['frontline'])+seasonpay)*q(f['other_operating_fraction_of_pay'])*q(f['other_operating_import_fraction'])/q(cfg['CU_per_FU']),'all_new_asset_quote_CU':stock,'renewal_CU':renew,'normal_import_FU':annualFX,'diesel_import_FU':diesel*q(f['diesel_FU_litre']),'initial_food_stock_FU':reservequote,'initial_seed_stock_FU':seedquote,'electricity_GWh':power,'food_potable_process_m3':cropgross*q(cfg['water']['food_potable_m3_processing_tonne']),'field_seed_variety_title_quality_and_worker_receiving':None}
